-- Load seed data for schema 'ecommerce'.
-- Run from this folder after creating the schema:  psql -d yourdb -f load_ecommerce.sql
\set ON_ERROR_STOP on
BEGIN;
SET search_path TO ecommerce;

-- Identity columns are GENERATED ALWAYS; allow explicit ids while loading.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name, column_name FROM information_schema.columns
           WHERE table_schema = 'ecommerce' AND is_identity = 'YES' AND identity_generation = 'ALWAYS' LOOP
    EXECUTE format('ALTER TABLE ecommerce.%I ALTER COLUMN %I SET GENERATED BY DEFAULT', r.table_name, r.column_name);
  END LOOP; END $$;

\copy customers (customer_id, email, password_hash, first_name, last_name, phone, is_guest, marketing_opt_in, email_verified_at, last_login_at, created_at, updated_at) FROM 'customers.csv' WITH (FORMAT csv, HEADER true)
\copy addresses (address_id, customer_id, full_name, line1, line2, city, state, postal_code, country, phone, is_default_shipping, is_default_billing) FROM 'addresses.csv' WITH (FORMAT csv, HEADER true)
\copy brands (brand_id, name, slug, logo_url) FROM 'brands.csv' WITH (FORMAT csv, HEADER true)
\copy categories (category_id, parent_id, name, slug, description, sort_order, is_active) FROM 'categories.csv' WITH (FORMAT csv, HEADER true)
\copy products (product_id, brand_id, name, slug, description, status, tax_class, attributes, created_at, updated_at) FROM 'products.csv' WITH (FORMAT csv, HEADER true)
\copy product_categories (product_id, category_id) FROM 'product_categories.csv' WITH (FORMAT csv, HEADER true)
\copy product_variants (variant_id, product_id, sku, barcode, option_values, price, compare_at_price, cost_price, currency_code, weight_grams, is_active, created_at, updated_at) FROM 'product_variants.csv' WITH (FORMAT csv, HEADER true)
\copy product_images (image_id, product_id, variant_id, url, alt_text, position) FROM 'product_images.csv' WITH (FORMAT csv, HEADER true)
\copy warehouses (warehouse_id, code, name, city, country, is_active) FROM 'warehouses.csv' WITH (FORMAT csv, HEADER true)
\copy coupons (coupon_id, code, description, discount_type, discount_value, min_order_amount, max_discount_amount, usage_limit, per_customer_limit, times_used, starts_at, expires_at, is_active) FROM 'coupons.csv' WITH (FORMAT csv, HEADER true)
\copy orders (order_id, order_number, customer_id, status, currency_code, subtotal, discount_total, shipping_total, tax_total, grand_total, coupon_id, shipping_address, billing_address, shipping_method, customer_note, placed_at, cancelled_at, updated_at) FROM 'orders.csv' WITH (FORMAT csv, HEADER true)
\copy order_items (order_item_id, order_id, variant_id, sku, product_name, quantity, unit_price, discount_amount, tax_amount, line_total) FROM 'order_items.csv' WITH (FORMAT csv, HEADER true)
\copy order_status_history (history_id, order_id, from_status, to_status, note, changed_at) FROM 'order_status_history.csv' WITH (FORMAT csv, HEADER true)
\copy payments (payment_id, order_id, provider, provider_payment_id, method, amount, currency_code, status, card_brand, card_last4, failure_code, created_at, captured_at) FROM 'payments.csv' WITH (FORMAT csv, HEADER true)
\copy refunds (refund_id, payment_id, amount, reason, provider_refund_id, created_at) FROM 'refunds.csv' WITH (FORMAT csv, HEADER true)
\copy shipments (shipment_id, order_id, warehouse_id, carrier, service_level, tracking_number, status, shipping_cost, shipped_at, estimated_delivery, delivered_at) FROM 'shipments.csv' WITH (FORMAT csv, HEADER true)
\copy shipment_items (shipment_id, order_item_id, quantity) FROM 'shipment_items.csv' WITH (FORMAT csv, HEADER true)
\copy returns (return_id, rma_number, order_id, status, reason, customer_comment, refund_id, requested_at, received_at) FROM 'returns.csv' WITH (FORMAT csv, HEADER true)
\copy return_items (return_id, order_item_id, quantity, condition, restock) FROM 'return_items.csv' WITH (FORMAT csv, HEADER true)
\copy inventory (variant_id, warehouse_id, quantity_on_hand, quantity_reserved, reorder_point, updated_at) FROM 'inventory.csv' WITH (FORMAT csv, HEADER true)
\copy inventory_movements (movement_id, variant_id, warehouse_id, quantity_change, reason, reference_id, created_at) FROM 'inventory_movements.csv' WITH (FORMAT csv, HEADER true)
\copy carts (cart_id, customer_id, session_token, coupon_id, created_at, updated_at) FROM 'carts.csv' WITH (FORMAT csv, HEADER true)
\copy cart_items (cart_id, variant_id, quantity, added_at) FROM 'cart_items.csv' WITH (FORMAT csv, HEADER true)
\copy wishlist_items (customer_id, variant_id, added_at) FROM 'wishlist_items.csv' WITH (FORMAT csv, HEADER true)
\copy reviews (review_id, product_id, customer_id, order_item_id, rating, title, body, is_approved, helpful_count, created_at) FROM 'reviews.csv' WITH (FORMAT csv, HEADER true)

-- Restore GENERATED ALWAYS and move sequences past the loaded ids.
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT table_name, column_name FROM information_schema.columns
           WHERE table_schema = 'ecommerce' AND is_identity = 'YES' LOOP
    EXECUTE format('SELECT setval(pg_get_serial_sequence(''ecommerce.%I'', %L), COALESCE((SELECT max(%I) FROM ecommerce.%I), 0) + 1, false)',
                   r.table_name, r.column_name, r.column_name, r.table_name);
    EXECUTE format('ALTER TABLE ecommerce.%I ALTER COLUMN %I SET GENERATED ALWAYS', r.table_name, r.column_name);
  END LOOP; END $$;

COMMIT;
